fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            // Split into lines; ensure the inner vector is non-empty.
            let mut parts: Vec<String> = if keepends {
                // Retain line endings when they exist.
                s.split_inclusive('\n').map(|p| p.to_string()).collect()
            } else {
                // Drop line endings.
                s.lines().map(|p| p.to_string()).collect()
            };

            // `lines()` yields empty for "", and `split_inclusive('\n')` yields empty for "" too.
            // Guarantee non-empty inner list by falling back to the original string.
            if parts.is_empty() {
                parts.push(s);
            }
            parts
        })
        .collect()
}